CREATE TABLE eznode_assignment (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, contentobject_id INTEGER DEFAULT NULL, contentobject_version INTEGER DEFAULT NULL, from_node_id INTEGER DEFAULT 0, is_main INTEGER DEFAULT 0 NOT NULL, op_code INTEGER DEFAULT 0 NOT NULL, parent_node INTEGER DEFAULT NULL, parent_remote_id VARCHAR(100) DEFAULT '' NOT NULL, remote_id VARCHAR(100) DEFAULT '0' NOT NULL, sort_field INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 1, priority INTEGER DEFAULT 0 NOT NULL, is_hidden INTEGER DEFAULT 0 NOT NULL);
